function origin(){return(process.env.ALPHALAB_API_ORIGIN||'http://127.0.0.1:8000').replace(/\/+$/,'')}
async function fetchJson(path,options={}){const response=await fetch(origin()+path,{headers:{Accept:'application/json','Content-Type':'application/json'},...options});if(!response.ok)throw new Error('AlphaLab API '+response.status+': '+await response.text());return response.json()}
async function run(input){const action=String(input.action||'');if(action==='list')return fetchJson('/api/reports?limit='+Math.max(1,Math.min(100,Number(input.limit||20))));if(action==='get'){const id=String(input.artifact_id||'').trim();if(!id)throw new Error('artifact_id is required for get');return fetchJson('/api/reports/'+encodeURIComponent(id))}if(action==='save'){if(input.confirm_write!==true)throw new Error('Saving a research report requires confirm_write=true');if(!input.workspace_result||!input.markdown)throw new Error('workspace_result and markdown are required for save');const result={...input.workspace_result,markdown:String(input.markdown)};return fetchJson('/api/reports',{method:'POST',body:JSON.stringify({profile:'runtime',result})})}throw new Error('unsupported research report action')}
